window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-400c41f458f95ca3"]={"versions": [{"id": "FIG-400c41f458f95ca3", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Kompositions- bzw. Blockschaltbild zur Veranschaulichung einer internen Hardware-Bustopologie im Kontext des AUTOSAR ECU Resource Template (<code>AUTOSAR_ResourceTemplateECU</code>). Dargestellt wird die Verschaltung mehrerer Hardware-Elemente innerhalb eines übergeordneten Hardware-Containers über einen gemeinsamen Verbindungsstrang.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>HW Container</strong>: Umfassender Rahmen/Container (<code>HwElement</code> bzw. zusammengesetzte Hardware-Entität), der vier Hardware-Komponenten kapselt.\n</li><li><strong>HW Element 1, HW Element 2, HW Element 3, HW Element 4</strong>: Einzelne Hardware-Bausteine bzw. Sub-Elemente (<code>HwElement</code>) innerhalb des Containers.\n</li><li><strong>Hardware-Pins / Kommunikationsports</strong>: Kleine quadratische Port-Symbole an den Kanten der jeweiligen Hardware-Elemente zur Anbindung an das Übertragungsmedium.\n</li><li><strong>Conn1</strong>: Hardware-Konnektor bzw. gemeinsame Busverbindung (<code>HwConnection</code>), die als verzweigtes Netz (H-förmige Bustopologie) alle vier Hardware-Elemente über ihre jeweiligen Ports elektrisch bzw. logisch miteinander koppelt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische topologische Struktur dar. Es sind keine dynamischen Interaktionen, Nachrichtensequenzen oder Zustandsübergänge abgebildet. Kommunikationsvorgänge erfolgen über die physikalische Busverbindung <code>Conn1</code> nach den jeweiligen protokollspezifischen Regeln der angebundenen Hardware-Elemente.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Exemplarische Darstellung für die Modellierung von Bus-Topologien mittels des AUTOSAR-Hardware-Ressourcen-Templates. Bei der XML-/ARXML-Modellierung werden die dargestellten Entitäten als Instanzen von Hardware-Elementen (<code>HwElement</code>) und deren Verbindungen (<code>HwConnection</code>) abgebildet, wobei Ports (<code>HwPin</code> / Verbindungsstellen) als Koppelpunkte zur Repräsentation gemeinsamer Busmedien dienen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-1420c102d9c45758", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Kompositions- bzw. Blockschaltbild zur Veranschaulichung einer internen Hardware-Bustopologie im Kontext des AUTOSAR ECU Resource Template (<code>AUTOSAR_ResourceTemplateECU</code>). Dargestellt wird die Verschaltung mehrerer Hardware-Elemente innerhalb eines übergeordneten Hardware-Containers über einen gemeinsamen Verbindungsstrang.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>HW Container</strong>: Umfassender Rahmen/Container (<code>HwElement</code> bzw. zusammengesetzte Hardware-Entität), der vier Hardware-Komponenten kapselt.\n</li><li><strong>HW Element 1, HW Element 2, HW Element 3, HW Element 4</strong>: Einzelne Hardware-Bausteine bzw. Sub-Elemente (<code>HwElement</code>) innerhalb des Containers.\n</li><li><strong>Hardware-Pins / Kommunikationsports</strong>: Kleine quadratische Port-Symbole an den Kanten der jeweiligen Hardware-Elemente zur Anbindung an das Übertragungsmedium.\n</li><li><strong>Conn1</strong>: Hardware-Konnektor bzw. gemeinsame Busverbindung (<code>HwConnection</code>), die als verzweigtes Netz (H-förmige Bustopologie) alle vier Hardware-Elemente über ihre jeweiligen Ports elektrisch bzw. logisch miteinander koppelt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische topologische Struktur dar. Es sind keine dynamischen Interaktionen, Nachrichtensequenzen oder Zustandsübergänge abgebildet. Kommunikationsvorgänge erfolgen über die physikalische Busverbindung <code>Conn1</code> nach den jeweiligen protokollspezifischen Regeln der angebundenen Hardware-Elemente.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Exemplarische Darstellung für die Modellierung von Bus-Topologien mittels des AUTOSAR-Hardware-Ressourcen-Templates. Bei der XML-/ARXML-Modellierung werden die dargestellten Entitäten als Instanzen von Hardware-Elementen (<code>HwElement</code>) und deren Verbindungen (<code>HwConnection</code>) abgebildet, wobei Ports (<code>HwPin</code> / Verbindungsstellen) als Koppelpunkte zur Repräsentation gemeinsamer Busmedien dienen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-400c41f458f95ca3", "to": "FIG-1420c102d9c45758", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
